/**
 * Messages, residential R6 (the reader's PR): the boxes `gmail-sync` reads, each as its own Gmail user under the service
 * account's domain-wide delegation. bids@ is today's, from the `GMAIL_IMPERSONATE_USER` secret (Settings' bids address
 * when the secret is empty). The team box is read only once Settings holds its address (`messages_boxes_v1.team`), so
 * nothing runs for it until the owner's team@ or office@ is typed and the delegation covers it. Pure, and light enough
 * for the edge copy (`scripts/edge-kernels.mjs`).
 */
import { boxSetting, type BoxSettings, type Mailbox } from '../messages/boxes.ts'

/** One box the reader reads: which, the Gmail user it reads as, and how a line names it ("bids@"). */
export interface ReaderBox {
  mailbox: Mailbox
  address: string
  /** The address's own part with its @, as a line's who says it: "bids@", "team@". */
  words: string
}

const key = (address: string) => address.trim().toLowerCase()

/** How a line names a box: "bids@clickconstruction.example" is "bids@". */
export function boxWords(address: string): string {
  const at = address.indexOf('@')
  return at > 0 ? `${address.slice(0, at).trim()}@` : address.trim()
}

/**
 * The boxes to read, bids@ first. bids@ is the secret's address, else Settings'. The team box is Settings' address alone,
 * and is left out while it is empty, not an address, or the same address as bids@'s.
 */
export function readerBoxes(settings: BoxSettings | null, bidsSecret: string | null | undefined): ReaderBox[] {
  const out: ReaderBox[] = []
  const bids = bidsSecret?.trim() || boxSetting('bids', settings).address
  if (bids.includes('@')) out.push({ mailbox: 'bids', address: bids, words: boxWords(bids) })
  const team = boxSetting('team', settings).address
  if (team.includes('@') && !out.some((b) => key(b.address) === key(team))) out.push({ mailbox: 'team', address: team, words: boxWords(team) })
  return out
}
